if(!s)throw new Error('Missing '+name);
var detail=s.layers.find(function(l){return l.name==='content-col';}).layers.find(function(l){return l.name==='main';}).layers.find(function(l){return l.name==='settings-split';}).layers.find(function(l){return l.name==='settings-detail';});
