if(phase==='detail'){detail.layers.slice().forEach(function(l){l.remove();});var hd=F({name:'detail-heading',parent:detail,dir:'col',gap:8,pad:0,w:824});T(hd,meta[1],{size:15,weight:6});T(hd,{account:'Your identity, workspace and signed-in devices.',devices:'Manage the Macs and iPhone connected to your account.',general:'Make Weave work the way you do.',appearance:'Choose how Weave looks on this Mac.',voice:'Natural conversations, on your terms.',notifications:'Choose when Weave asks for your attention.',connections:'Bring your tools into the conversation.',billing:'Your plan and usage, all in one place.',privacy:'You control your conversations and your data.',shortcuts:'Keep your hands on the keyboard.',about:'A thoughtful workspace for working with AI.'}[cat],{size:12,color:H.sw(APP,'tertiary')});H.order(hd);
// CONTENT
H.order(detail);detail.parent.stackLayout.apply();s.frame.x=IDS.indexOf(ID)*1560;s.frame.y=2120;
}
if(phase==='overlay'){H.macScrim(s,APP);
if(ID==='settings--sign-out'){var a=H.macAlert(s,APP,{title:'Sign out of this Mac?',body:'Local agents will stop and this Mac will be disconnected. Your conversations and files stay in your account.',glyph:'person',w:360,buttons:[['back','Cancel','secondary'],['signin','Sign out','primary']]});a.style.borders=[];a.style.fills=[{color:H.sw(APP,'panel')}];a.layers.forEach(function(l){if(l.name==='icon'){l.style.fills=[];l.frame.width=32;l.frame.height=32;l.layers.forEach(function(g){g.style.fontSize=24;});}if(l.type==='Text'&&l.style.fontSize===11)l.style.fontSize=12;if(l.name==='buttons')l.layers.forEach(function(b){b.style.borders=[];b.style.shadows=[];b.style.fills=[{color:H.sw(APP,b.name==='link:signin'?'ink':'hover')}];b.layers.forEach(function(t){t.style.textColor=H.sw(APP,b.name==='link:signin'?'surface':'ink');});b.style.corners.radii=[999,999,999,999];});});a.stackLayout.apply();}
else{var sh=F({name:'plan-sheet',parent:s,dir:'col',gap:24,pad:24,w:560,radius:16,fill:H.sw(APP,'panel'),shadow:{color:'#00000040',blur:32,x:0,y:16,spread:0}});T(sh,'Change plan',{size:15,weight:6});T(sh,'Room for your next idea, or your whole team.',{size:12,color:H.sw(APP,'tertiary')});[['Free','S$0 / month','50,000 tokens · 1 device'],['Pro','S$32 / month','500,000 tokens · 5 devices · Renews 14 Oct 2026'],['Team','S$96 / month','2 million tokens · Shared workspace']].forEach(function(p,i){var r=F({name:'link:settings-billing',parent:sh,dir:'row',gap:12,pad:0,w:512,h:64});var tx=F({name:'plan-copy',parent:r,dir:'col',gap:6,pad:0});T(tx,p[0],{weight:6});T(tx,p[2],{size:12,color:H.sw(APP,'tertiary'),w:320});H.order(tx);space(r);T(r,p[1]);var ck=F({name:'selection',parent:r,pad:0,w:16,h:16});if(i===1)H.sfg(ck,'checkmark_circle_fill',{size:16,color:H.sw(APP,'accent')});H.order(ck);H.order(r);});T(sh,'Prices in Singapore dollars. Changes apply at your next renewal.',{size:12,color:H.sw(APP,'tertiary'),w:512});var acts=F({name:'sheet-actions',parent:sh,pad:0,gap:8,w:512,h:28});space(acts);button(acts,'Cancel','back');button(acts,'Done','settings-billing','primary');H.order(acts);H.order(sh);sh.frame.x=568;sh.frame.y=52;sh.moveToFront();}}
